# Bám sách: trang 94–95 + đáp án + Mini dictionary unit 45. Không chép nguyên văn.
theory = (
 H("A", "Dialogues", "Các đoạn hội thoại")
 + P("In each short dialogue, the second speaker answers using a phrasal verb about speaking.", "Trong mỗi đoạn hội thoại ngắn, người nói thứ hai đáp lại bằng một phrasal verb về cách nói.")
 + T([
    ("<b>go on at</b>", "A child tells a parent to stop criticising him all the time about revision.", "Đứa con bảo bố mẹ thôi chỉ trích mình mãi chuyện ôn bài."),
    ("<b>run through</b>", "Paul will quickly explain the main points of the meeting to Jackson.", "Paul sẽ nói nhanh các ý chính của cuộc họp cho Jackson."),
    ("<b>hold forth</b>", "Maya thinks a two-hour presentation is too long: nobody wants to listen to someone talking on and on.", "Maya cho rằng thuyết trình hai tiếng là quá dài: không ai muốn nghe một người nói mãi không dứt."),
    ("<b>gloss over</b>", "Eloise suggests stressing the good points to the committee and not discussing the difficult parts in detail.", "Eloise đề nghị nhấn mạnh điểm tốt trước hội đồng và không đi sâu vào những phần khó."),
    ("<b>engage</b> sb <b>in conversation</b>", "Lauren will start talking to Richard so that Albert can bring in his present.", "Lauren sẽ bắt chuyện với Richard để Albert mang quà vào."),
 ])
 + H("B", "More phrasal verbs connected with speaking", "Thêm phrasal verb về cách nói")
 + T([
    ("<b>reel off</b>", "(informal) Mr Holroyd said a long list of names quickly, without stopping.", "(thân mật) Ông Holroyd đọc một tràng tên liền một mạch."),
    ("<b>wring</b> sth <b>out of</b> / <b>drag</b> sth <b>out of</b>", "Detectives tried to force the truth from a suspect; someone threatens to make another person tell the truth.", "Thám tử cố ép nghi phạm khai sự thật; một người dọa sẽ moi sự thật từ người kia."),
    ("<b>bombard</b> sb <b>with</b> / <b>put</b> sth <b>to</b>", "Reporters directed many questions at a minister; someone raised a hand to ask the speaker a question.", "Phóng viên hỏi dồn dập một bộ trưởng; có người giơ tay đặt câu hỏi cho diễn giả."),
    ("<b>talk at</b>", "She talked to the speaker for an hour without listening or letting her speak.", "Cô ấy nói một chiều suốt một tiếng, không nghe cũng không để người kia nói."),
    ("<b>blurt out</b>", "He suddenly said, without thinking, the name of a star’s hotel.", "Anh ta buột miệng nói ra tên khách sạn nơi ngôi sao ở."),
    ("<b>expand on</b>", "One person gives the general plan, the other adds details.", "Một người giới thiệu khái quát kế hoạch, người kia nói chi tiết hơn."),
    ("<b>dry up</b> / <b>clam up</b>", "The speaker stopped in the middle of a welcome speech, having forgotten what to say; a nervous pupil (informal) went silent.", "Người nói tắc lời giữa bài phát biểu chào mừng vì quên mất; một cậu học trò run quá nên (thân mật) im bặt."),
    ("<b>sound out</b>", "Before getting a flat, the speaker must find out what the parents think.", "Trước khi ra ở riêng, người nói phải thăm dò ý bố mẹ."),
    ("<b>lead into</b>", "A conversation about the Olympics was the reason a discussion about drugs started.", "Câu chuyện về Olympic dẫn sang bàn về chuyện doping."),
 ])
 + NOTE("<b>Exercise 45.4 adds</b>: <b>cut in on</b> (interrupt a conversation, see Unit 11), <b>explain away</b> (give a reason for something bad so it seems not your fault, e.g. a scratch on your mother’s car), <b>witter on</b> (talk endlessly, e.g. about the weather).",
        "<b>Bài 45.4 bổ sung</b>: <b>cut in on</b> (chen ngang câu chuyện, xem bài 11), <b>explain away</b> (đưa lý do cho việc xấu để có vẻ không phải lỗi mình, ví dụ vết xước trên xe của mẹ), <b>witter on</b> (nói mãi không dứt, ví dụ về thời tiết).")
)
